    /**
     * Función que se utiliza para cargar a estructura del DPA
     *
     * @param int $id
     * @param int $idpais Identificador de país
     *
     * @return array
     */
    static function cargarEstructura($id, $idpais)
    {
        $q = Doctrine_Query::create();
        $where = ($id == 'idpadre')
            ? "iddpt = idpadre and idpais = $idpais and fechafin is null"
            : "idpadre = $id
            and idpais = $idpais and iddpt<>idpadre and fechafin is null";

        $result = $q->select(
            'a.iddpt,a.iddpt id,a.denominacion, a.denominacion text,a.idpadre,
             a.abreviatura,a.abreviatura alias,
             a.fechafin, a.fechainicio, a.idpais,a.idnivelestructural,
             a.codigo, b.idconceptonivel, b.raiz as raiz,
             k.denominacion as tpest,
             k.idconceptonivel,(a.ordender - a.ordenizq = 1) as leaf'
        )
            ->from('NomDpasecodena a')
            ->innerJoin(
                'a.NomNivelestructural b
                on a.idnivelestructural = b.idnivelestructural'
            )
            ->innerJoin('b.NomConceptonivel k ')
            ->where($where)
            ->orderby('iddpt')
            ->execute()->toArray();


        return $result;
    }

