    /**
     * Para que devuelve los padres de un nodo determinado
     *
     * @param int $iddpt Identificador de División Político Territorial
     *
     * @return array
     */
    static function buscarPadres($iddpt)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getConnection('configsecodena');
        $sql = "SELECT n.iddpt AS iddpt, n.denominacion
                AS text,n.idnivelestructural,
                (n.ordender - n.ordenizq) = 1 as leaf, n.idpadre, n.iddpt AS id
                FROM mod_datosmaestros.nom_dpt n
                WHERE (ordenizq <= (select ordenizq
                from mod_datosmaestros.nom_dpt where iddpt=$iddpt)
                AND ordender >= (select ordender
                from mod_datosmaestros.nom_dpt where iddpt=$iddpt))
                ORDER BY n.ordenizq";

        return $conn->fetchAll($sql);
    }

    /**
     * Función que se utiliza para retornar el elemento pasado su id
     *
     * @param int $iddpt Identificador de División Político Territorial
     *
     * @return array
     */
    static function getRutaDPT($iddpt)
    {
        $_dpt = Doctrine::getTable('NomDpasecodena')->find($iddpt);
        $_rama = '';
        if ($_dpt) {
            $q = Doctrine_Query::create();
            $result = $q->from('NomDpasecodena')
                ->where(
                    "ordenizq <= ? and ordender >= ?",
                    array($_dpt->ordenizq, $_dpt->ordender)
                )
                ->orderBy('ordenizq')
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
            if ($result[0]) {
                $_pais = Doctrine::getTable('NomPaissecodena')->find(
                    $result[0]['idpais']
                );
                if ($_pais) {
                    $_rama = $_pais->nombrepais;
                    $ini = 0;
                } else {
                    $_rama = $result[0]['denominacion'];
                    $ini = 1;
                }
                for ($i = $ini; $i < count($result); $i++) {
                    $_rama .= '=>' . $result[$i]['denominacion'];
                }
            }
        }
        return $_rama;
    }

