    /**
     * Para devolver si el nodo2 es hijo del nodo1
     *
     * @param int $idpadre Identificador de padre
     * @param int $idhijo  Identificador de hijo
     *
     * @return bool
     */
    static function dimesieshijo($idpadre, $idhijo)
    {
        $q = Doctrine_Query::create();
        $resultpadre = $q->select(
            'iddpt id, denominacion text,idpadre, abreviatura,
            fechafin, fechainicio, codigo,
            (ordender - ordenizq = 1) as leaf'
        )->from('NomDpasecodena')->where("iddpt=?", $idpadre)->execute()
            ->toArray();
        $resulhijo = $q->select(
            'iddpt id, denominacion text,idpadre, abreviatura,
             fechafin, fechainicio, codigo,
            (ordender - ordenizq = 1) as leaf'
        )
            ->from('NomDpasecodena')->where("iddpt=?", $idhijo)->execute()
            ->toArray();
        if (($resulhijo [0] ['ordenizq'] > $resultpadre [0] ['ordenizq'])
            && ($resulhijo [0] ['ordender'] < $resultpadre [0] ['ordender'])
        ) {

            return true; //Retorno verdadero si es hijo
        } else {
            return false;
        }
    }

    /**
     * Obtiene los niveles dado el país
     *
     * @param int $idpais Identificador de país
     *
     * @return array
     */
    public function obtenerNivelesDadoPais($idpais)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getConnection('configsecodena');
        $sql = "SELECT DISTINCT(n.idnivelestructural) AS idnivelestructural,
                n3.denominacion AS denominacion
                FROM mod_datosmaestros.nom_dpt n
                INNER JOIN mod_configsecodena.nom_nivelestructural n2
                ON n.idnivelestructural = n2.idnivelestructural
                INNER JOIN mod_configsecodena.nom_conceptonivel n3 
                ON n2.idconceptonivel = n3.idconceptonivel
                WHERE (n.idpais = $idpais)";
        return $conn->fetchAll($sql);
    }

