    /**
     * Obtiene el DPA hijos dado un arreglo de ID
     *
     * @param array $strpadres
     * @param mixed $node
     * @param bool  $chk
     *
     * @return array
     */
    static public function getDpaDadoArrayIdsHijos(
        $strpadres, $node, $chk = false
    ) {
        $query = Doctrine_Query::create();
        $checked = ($chk) ? ",false as checked" : "";
        $padre = ($node == '0') ? ' n.idpadre = n.iddpt '
            : " n.idpadre = $node  AND n.iddpt <> $node";
        return $query->select(
            "n.iddpt id, n.denominacion text, ( (n.ordender - n.ordenizq) = 1)
    leaf, n.iddpt, n.idpadre, n.ordender, n.ordenizq" . $checked
        )
            ->from('NomDpasecodena n')->where(
                $padre . ' AND (' . $strpadres . ')'
            )->setHydrationMode(
                Doctrine::HYDRATE_ARRAY
            )->execute();
    }

    /**
     * Servicio que dado el concepto de nivel brinda los niveles
     * estructurales definidos para ese pais.
     *
     * @param int $idpais          Identificador de país
     * @param int $idconceptoNivel Identificador concepto nivel
     *
     * @return array
     * @throws Doctrine_Exception
     */
    static public function getNivelEstructuralPorPais($idpais, $idconceptoNivel)
    {
        try {
            $query = new Doctrine_Query();
            $result = $query->select('ndpt.*')
                ->from('NomDpasecodena ndpt')
                ->innerJoin('ndpt.NomNivelestructural ne')
                ->where(
                    "ne.idconceptonivel='$idconceptoNivel'
                    AND ndpt.idpais='$idpais'"
                )
                ->execute()->toArray();
            return $result;
        } catch (Doctrine_Exception $ee) {
            throw $ee;
        }
    }

    /**
     * Dado el objeto dpa te devuelve si esta presente en la tabla uno
     * con la misma denominación.
     *
     * @param object $obj dpa
     *
     * @return bool
     */
    static public function verificarDenominacion($obj)
    {
        $idpadre = $obj->idpadre;
        $denominacion = $obj->denominacion;
        $query = Doctrine_Query::create();
        ($idpadre == 0)
            ?
            $nombreCliente = $query->select('ndpt.*')
                ->from('NomDpasecodena ndpt')
                ->where(
                    "(ndpt.denominacion iLIKE '$denominacion'
                    AND ndpt.idpadre=ndpt.iddpt)
                    AND (ndpt.fechafin is Null OR ndpt.fechafin >= now())"
                )
                ->setHydrationMode(Doctrine_Core::HYDRATE_ARRAY)
                ->execute()
            :
            $nombreCliente = $query->select('ndpt.*')
                ->from('NomDpasecodena ndpt')
                ->where(
                    "(ndpt.denominacion iLIKE '$denominacion'
                     AND ndpt.idpadre='$idpadre'
                     AND (ndpt.fechafin is Null OR ndpt.fechafin >= now())"
                )
                ->setHydrationMode(Doctrine_Core::HYDRATE_ARRAY)
                ->execute();
        if (count($nombreCliente) > 0) {
            return false;
        }
        return true;
    }

