    /**
     * Verifica el codigo al modificar
     *
     * @param object $obj dpa
     *
     * @return bool
     */
    static public function verificarCod($obj)
    {
        $codigo = $obj->codigo;
        $iddpt = $obj->iddpt;
        $idpadre = $obj->idpadre;
        $query = Doctrine_Query::create();
        $nombreCliente = $query->select('ndpt.*')
            ->from('NomDpasecodena ndpt')
            ->where(
                "( ndpt.codigo = '$codigo')
                    AND (ndpt.fechafin is Null OR ndpt.fechafin >= now())
                     AND ndpt.iddpt<>$iddpt AND ndpt.idpadre = '$idpadre'"
            )
            ->setHydrationMode(Doctrine_Core::HYDRATE_ARRAY)
            ->execute();
        if (count($nombreCliente) > 0) {
            return false;
        }
        return true;
    }

