    }

    /**
     * Obtener el primer nivel del DPA es decir los estados o provincias.
     *
     * @param array $argIdpais ID Pa&iacute;s
     *
     * @return array
     */
    static function obtenerListadoPrimerNivel($argIdpais)
    {
        $query = new Doctrine_Query();
        $estados = $query
            ->select(
        'dpt.iddpt ,dpt.iddpt as id, dpt.denominacion, dpt.denominacion as text,
        dpt.idpadre, dpt.abreviatura, dpt.abreviatura as alias, dpt.fechafin,
        dpt.fechainicio, dpt.idpais,
        dpt.idnivelestructural, dpt.codigo, nv.idconceptonivel,
         nv.idconceptonivel as idconceptonivel,
        nv.raiz as raiz, nc.denominacion as conceptonivel, nc.idconceptonivel,
        (dpt.ordender - dpt.ordenizq = 1) as leaf'
            )
            ->from('NomDpa dpt')
            ->innerJoin(
                'dpt.NomNivelestructural nv
                on dpt.idnivelestructural = nv.idnivelestructural'
            )
            ->innerJoin('nv.NomConceptonivel nc ')
            ->where(
                'dpt.idpais = ? and (dpt.iddpt is NULL
                or dpt.iddpt = dpt.idpadre)',
                $argIdpais
            )
            ->orderby('dpt.iddpt')
            ->setHydrationMode(Doctrine::HYDRATE_RECORD)
            ->execute();
        if ($estados->count() > 0) {
            $result = $estados->toArray();
            foreach ($result as $index) {
                unset($result[$index]['NomNivelestructural']);
            }
        } else {
            $result = array();
        }
        return $result;
    }

